      if (args.length < 2) {
         sender.sendMessage(ChatColor.RED + "Incorrect usage. Correct usage:\n" + this.usageMessage);
         return false;
      } else {
         int value;
         Iterator var5;
         World world;
         if (args[0].equals("set")) {
            if (!sender.hasPermission("bukkit.command.time.set")) {
